INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Ticketsystem ein zentrales Werkzeug im Fehlermanagement?', 2, '[{"text": "Ja", "correct": true, "because": "Verwaltet Fehler effizient"}, {"text": "Nein", "correct": false, "because": "Es ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt ein Ticketsystem?', 3, '[{"text": "Fehler und Anfragen strukturiert verwalten", "correct": true, "because": "Fördert Nachverfolgung"}, {"text": "Projektziele definieren", "correct": false, "because": "Initiierungsschritt"}, {"text": "Team direkt einteilen", "correct": false, "because": "Projektleiteraufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Ticketsystem erfasst Fehler. b) Es wird nur im Abschluss genutzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, fortlaufend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bietet ein Ticketsystem?', 4, '[{"text": "Fehlererfassung", "correct": true, "because": "Registriert Probleme"}, {"text": "Unklare Zuweisung", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Priorisierung", "correct": true, "because": "Bestimmt Dringlichkeit"}, {"text": "Statusverfolgung", "correct": true, "because": "Überwacht Bearbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Ticketsystem Fehler effizient verwalten?', 2, '[{"text": "Nein", "correct": true, "because": "Struktur und Übersicht fehlen"}, {"text": "Ja", "correct": false, "because": "Manuell ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ein Ticketsystem im Controlling?', 3, '[{"text": "Fehlerstatus und Lösungen überwachen", "correct": true, "because": "Sichert Fortschritt"}, {"text": "Projekt neu finanzieren", "correct": false, "because": "Auftraggeberaufgabe"}, {"text": "Zeitplan erstellen", "correct": false, "because": "Planungsaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Ticketsystem nur für technische Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch organisatorische Fehler"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe gehört zum Ticketsystem?', 3, '[{"text": "Tickets zuweisen und verfolgen", "correct": true, "because": "Fördert Bearbeitung"}, {"text": "Projektziele neu setzen", "correct": false, "because": "Auftraggeberaufgabe"}, {"text": "Team extern finanzieren", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Ticketsystem automatisiert Prozesse. b) Es ist immer manuell.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft automatisiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Ticketsystem?', 3, '[{"text": "Fehlerbearbeitung wird unübersichtlich", "correct": true, "because": "Keine Struktur"}, {"text": "Fehler verschwinden", "correct": false, "because": "Eher Ansammlung"}, {"text": "Qualität steigt", "correct": false, "because": "Qualität leidet"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Ticketsystem ohne Priorisierung arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Dringlichkeit unklar"}, {"text": "Ja", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt die Nutzung eines Ticketsystems?', 3, '[{"text": "Ticket für Softwarefehler erstellen", "correct": true, "because": "Konkret und real"}, {"text": "Fehler ignorieren", "correct": false, "because": "Kein Management"}, {"text": "Team soll etwas tun", "correct": false, "because": "Zu vage"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Ticketsystem nur für die Durchführung wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Planung und Abschluss"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein effektives Ticketsystem?', 4, '[{"text": "Automatische Zuweisung", "correct": true, "because": "Fördert Effizienz"}, {"text": "Unklare Status", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Fehlerkategorisierung", "correct": true, "because": "Fördert Ordnung"}, {"text": "Nachverfolgbarkeit", "correct": true, "because": "Sichert Dokumentation"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Ticketsystem dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachweis und Übersicht"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ein Ticketsystem im Team?', 3, '[{"text": "Fehler effizient verteilen und lösen", "correct": true, "because": "Fördert Zusammenarbeit"}, {"text": "Projekt neu planen", "correct": false, "because": "Planungsaufgabe"}, {"text": "Team finanzieren", "correct": false, "because": "Auftraggeberaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Ticketsystem ohne Kommunikation funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Abstimmung nötig"}, {"text": "Ja", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Nutzung eines Ticketsystems?', 3, '[{"text": "Fehlende Schulung", "correct": true, "because": "Verhindert Effizienz"}, {"text": "Klarer Prozess", "correct": false, "because": "Fördert Nutzung"}, {"text": "Gute Software", "correct": false, "because": "Unterstützt System"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Ticketsystem fördert Transparenz. b) Es ist nur für externe Fehler.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch intern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen eines Ticketsystems?', 3, '[{"text": "Schnelle Fehlerbehebung", "correct": true, "because": "Fördert Qualität"}, {"text": "Maximale Unordnung", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Nachverfolgung", "correct": false, "because": "Fördert Übersicht"}]');
